import { Component, OnInit } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service'  ;
import { UsuarioService } from 'src/app/services/usuario.service';
import { Usuario } from 'src/app/models/usuario';

@Component({
  selector: 'app-total-compras-todos-usuarios',
  templateUrl: './total-compras-todos-usuarios.component.html',
  styleUrls: ['./total-compras-todos-usuarios.component.css']
})
export class TotalComprasTodosUsuariosComponent implements OnInit{


  public totalCompras: number = 0;

  constructor(private misComprasService: MisComprasService, private usuarioService: UsuarioService){}

  ngOnInit(): void {
    this.contarComprasUsuarios();
  }

  contarComprasUsuarios(): void {
    this.usuarioService.getUsuarios().subscribe({
      next: (usuarios: Usuario[]) => {
        usuarios.forEach((usuario) => {
          this.misComprasService.obtenerComprasUsuario(usuario.email).subscribe({
            next: (compras: any[]) => { // Asegúrate de que el tipo es correcto
              compras.forEach(compra => {
                this.totalCompras += compra.total;
              });
            },
            error: (error) => console.error('Error al obtener compras del usuario', usuario.email, error)
          });
        });
      },
      error: (error) => console.error('Error al obtener usuarios', error)
    });
  }

}
